const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([73.931617, 31.998723]);
    const aoi = point.buffer(10000); // 10km radius
    const startDate2003 = '2003-01-01';
    const endDate2003 = '2003-12-31';
    const startDate2013 = '2013-01-01';
    const endDate2013 = '2013-12-31';

    // 2. Data Acquisition
    const graceCollection = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND')
        .select('lwe_thickness_csr');

    const col2003 = graceCollection.filterDate(startDate2003, endDate2003);
    const col2013 = graceCollection.filterDate(startDate2013, endDate2013);

    // 3. Data Availability Check
    const count2003 = col2003.size().getInfo();
    const count2013 = col2013.size().getInfo();

    if (count2003 === 0 || count2013 === 0) {
        console.log(`Image count 2003: ${count2003}`);
        console.log(`Image count 2013: ${count2013}`);
        console.log("Empty Collection: No GRACE data found for one or both years.");
        console.log("C1");
        return;
    }
    console.log(`Image count 2003: ${count2003}`);
    console.log(`Image count 2013: ${count2013}`);

    // 4. Processing and Calculation
    const mean2003 = col2003.mean();
    const mean2013 = col2013.mean();

    const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats2003 = mean2003.reduceRegion({
        reducer: reducer,
        geometry: aoi,
        scale: 10000, // GRACE data is coarse resolution
        maxPixels: 1e9
    }).getInfo();

    const stats2013 = mean2013.reduceRegion({
        reducer: reducer,
        geometry: aoi,
        scale: 10000,
        maxPixels: 1e9
    }).getInfo();

    const val2003 = stats2003['lwe_thickness_csr_mean'];
    const pixels2003 = stats2003['lwe_thickness_csr_count'];
    const val2013 = stats2013['lwe_thickness_csr_mean'];
    const pixels2013 = stats2013['lwe_thickness_csr_count'];

    // 5. Validation & Final Answer
    if (pixels2003 === 0 || pixels2013 === 0) {
        console.log(`Valid pixels 2003: ${pixels2003}`);
        console.log(`Valid pixels 2013: ${pixels2013}`);
        console.log("No Valid Pixels: The region of interest contained no data.");
        console.log("C2");
        return;
    }

    if (val2003 === null || val2013 === null) {
        console.log("Calculation Failure: Could not derive a mean value.");
        console.log(`Result 2003: ${val2003}`);
        console.log(`Result 2013: ${val2013}`);
        console.log("C3");
        return;
    }

    console.log(`2003 Avg. LWE Thickness (cm): ${val2003.toFixed(2)}`);
    console.log(`2013 Avg. LWE Thickness (cm): ${val2013.toFixed(2)}`);

    // A decline is indicated by a lower (more negative) Liquid Water Equivalent thickness
    if (val2013 < val2003) {
        console.log("Evidence: The average liquid water equivalent thickness was lower in 2013 than in 2003.");
        console.log("A");
    } else {
        console.log("Evidence: The average liquid water equivalent thickness did not decline between 2003 and 2013.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
